# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_spans


class RoundSpansTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        result = round_spans([Span(9 * 60 + 4, 17 * 60 + 12)], 15)
        self.assertEqual(result, ["09:00-17:15 (8h 15m)"])

    def test_halves_round_up(self):
        result = round_spans([Span(9 * 60 + 7, 10 * 60 + 22)], 15)
        self.assertEqual(result, ["09:00-10:15 (1h 15m)"])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(60, 120)], step)
